        internal static Js formatGenerated(Js iso)
        {
            if ((!iso))
            {
                return Js.S("");
            }
            Js d = Shared.parseTimestamp(iso);
            if (Js.IsNaN(d.GetTime()))
            {
                return iso;
            }
            Js p = Js.Fn(args1_ =>
            {
                Js n = Js.Arg(args1_, 0);
                return Js.ToStringValue(n).PadStart(Js.N(2d), Js.S("0"));
            });
            return Js.Cat(d.GetUtcFullYear().Str(), "-", p.Call(Js.Add(d.GetUtcMonth(), Js.N(1d))).Str(), "-", p.Call(d.GetUtcDate()).Str(), " ", p.Call(d.GetUtcHours()).Str(), ":", p.Call(d.GetUtcMinutes()).Str(), " UTC");
        }

