                    Js sev = (entry.Get("Severity").NonNullish ?? Js.S(""));
                    Js src2 = (entry.Get("Source") ? Js.Cat("<div class=\"source\">", Shared.esc(bl.Call(Js.S("source"))).Str(), ": ", Shared.esc(entry.Get("Source")).Str(), "</div>") : Js.S(""));
                    return Js.Cat("<div class=\"dosha-block ", Shared.esc(sev).Str(), "\"><div class=\"header-row\"><span class=\"name\">", Shared.esc(KundliBrihad.doshaNameLabel(bl, entry, nameKey)).Str(), "</span><span class=\"severity\">", Shared.esc(KundliBrihad.severityLabel(bl, sev)).Str(), "</span></div><p>", Shared.esc(entry.Get("Body")).Str(), "</p>", src2.Str(), "</div>");
                });
                doshasSection = Js.Cat("<h2>", Shared.esc(bl.Call(Js.S("section_doshas"))).Str(), "</h2>\n", block.Call(dd.Get("Mangal"), Js.S("dosha_mangal")).Str(), block.Call(dd.Get("KaalSarp"), Js.S("dosha_kaalsarp")).Str(), block.Call(dd.Get("Pitra"), Js.S("dosha_pitra")).Str());
            }
            Js bodyHtml = Js.Arr(cover, ascendant, planetsTable, housesSection, yogasSection, dashaSection, doshasSection, panchangTable, narratives).Filter(Js.BooleanFunction).Join(Js.S("\n\n"));
            return Shared.layoutDocument(Js.Obj(
                Js.Prop("lang", data.Get("Locale")),
                Js.Prop("title", Js.Cat(t.Call(Js.S("title_kundli")).Str(), " — ", (subject.Get("Name").NonNullish ?? Js.S("")).Str())),
                Js.Prop("branding", resolved),
                Js.Prop("bodyHtml", bodyHtml),
                Js.Prop("extraCss", KundliDetailed.MIDTIER_CSS)));
        }
    }
}
